//! Q compares a string of six thousand characters by its whole value.

use andromeda_test_suite::{broker, identity_matcher::has_id, namespace::Namespace, outcome::Done};
use googletest::prelude::*;
use ngsi_ld::{http::operation::QueryMethod, model::Entity, query::q};

/// Pins: Over one Building holding essay, a String of 6,001 characters starting with m, and note "short", each of
/// 14 q expressions sent in a Query body (equality with the String and with the String less its last character,
/// inequality, ordering against a and z, a range, a pattern from its middle and an absent anchored one with their
/// negations, existence, and note equal to the String) selects the Building exactly when essay or note satisfies it
/// Clause: 4.9, 5.7.2, 6.23.3.1
#[gtest]
#[tokio::test]
async fn n_qry_qlg_9054_q_compares_a_string_of_six_thousand_characters_by_its_whole_value() -> Result<()> {
    let namespace = Namespace::fresh();
    let broker = broker::front()?;
    let building_essay_id = namespace.urn("Building", "essay")?;
    let building_type = namespace.entity_type("Building")?;
    let building_essay = Entity::builder()
        .id(building_essay_id.clone())
        .entity_type(building_type.clone())
        .property("essay", "")
        .property("note", "short")
        .build()?;
    broker.entities().create(&building_essay).send().await?.done()?;
    let page = broker.entities().query().method(QueryMethod::Post).ids(vec![building_essay_id.clone()]).entity_type(&building_type).q(q::attr("essay").eq("")).send().await?;
    expect_that!(page.items(), len(eq(1)));
    expect_that!(page.items(), contains(has_id(&building_essay_id)));
    let page_2 = broker.entities().query().method(QueryMethod::Post).ids(vec![building_essay_id.clone()]).entity_type(&building_type).q(q::attr("essay").eq("")).send().await?;
    expect_that!(page_2.items(), len(eq(0)));
    let page_3 = broker.entities().query().method(QueryMethod::Post).ids(vec![building_essay_id.clone()]).entity_type(&building_type).q(q::attr("essay").ne("")).send().await?;
    expect_that!(page_3.items(), len(eq(0)));
    let page_4 = broker
        .entities()
        .query()
        .method(QueryMethod::Post)
        .ids(vec![building_essay_id.clone()])
        .entity_type(&building_type)
        .q(q::attr("essay").ne("short"))
        .send()
        .await?;
    expect_that!(page_4.items(), len(eq(1)));
    expect_that!(page_4.items(), contains(has_id(&building_essay_id)));
    let page_5 = broker
        .entities()
        .query()
        .method(QueryMethod::Post)
        .ids(vec![building_essay_id.clone()])
        .entity_type(&building_type)
        .q(q::attr("essay").gt("a"))
        .send()
        .await?;
    expect_that!(page_5.items(), len(eq(1)));
    expect_that!(page_5.items(), contains(has_id(&building_essay_id)));
    let page_6 = broker
        .entities()
        .query()
        .method(QueryMethod::Post)
        .ids(vec![building_essay_id.clone()])
        .entity_type(&building_type)
        .q(q::attr("essay").lt("a"))
        .send()
        .await?;
    expect_that!(page_6.items(), len(eq(0)));
    let page_7 = broker
        .entities()
        .query()
        .method(QueryMethod::Post)
        .ids(vec![building_essay_id.clone()])
        .entity_type(&building_type)
        .q(q::attr("essay").lt("z"))
        .send()
        .await?;
    expect_that!(page_7.items(), len(eq(1)));
    expect_that!(page_7.items(), contains(has_id(&building_essay_id)));
    let page_8 = broker
        .entities()
        .query()
        .method(QueryMethod::Post)
        .ids(vec![building_essay_id.clone()])
        .entity_type(&building_type)
        .q(q::attr("essay").within("a", "z"))
        .send()
        .await?;
    expect_that!(page_8.items(), len(eq(1)));
    expect_that!(page_8.items(), contains(has_id(&building_essay_id)));
    let page_9 = broker
        .entities()
        .query()
        .method(QueryMethod::Post)
        .ids(vec![building_essay_id.clone()])
        .entity_type(&building_type)
        .q(q::attr("essay").matches("\"yio3iuxr7ze5ednq\""))
        .send()
        .await?;
    expect_that!(page_9.items(), len(eq(1)));
    expect_that!(page_9.items(), contains(has_id(&building_essay_id)));
    let page_10 = broker
        .entities()
        .query()
        .method(QueryMethod::Post)
        .ids(vec![building_essay_id.clone()])
        .entity_type(&building_type)
        .q(q::attr("essay").matches("\"^zzz\""))
        .send()
        .await?;
    expect_that!(page_10.items(), len(eq(0)));
    let page_11 = broker
        .entities()
        .query()
        .method(QueryMethod::Post)
        .ids(vec![building_essay_id.clone()])
        .entity_type(&building_type)
        .q(q::attr("essay").not_matches("\"yio3iuxr7ze5ednq\""))
        .send()
        .await?;
    expect_that!(page_11.items(), len(eq(0)));
    let page_12 = broker
        .entities()
        .query()
        .method(QueryMethod::Post)
        .ids(vec![building_essay_id.clone()])
        .entity_type(&building_type)
        .q(q::attr("essay").not_matches("\"^zzz\""))
        .send()
        .await?;
    expect_that!(page_12.items(), len(eq(1)));
    expect_that!(page_12.items(), contains(has_id(&building_essay_id)));
    let page_13 = broker
        .entities()
        .query()
        .method(QueryMethod::Post)
        .ids(vec![building_essay_id.clone()])
        .entity_type(&building_type)
        .q(q::attr("essay").exists())
        .send()
        .await?;
    expect_that!(page_13.items(), len(eq(1)));
    expect_that!(page_13.items(), contains(has_id(&building_essay_id)));
    let page_14 = broker.entities().query().method(QueryMethod::Post).ids(vec![building_essay_id.clone()]).entity_type(&building_type).q(q::attr("note").eq("")).send().await?;
    expect_that!(page_14.items(), len(eq(0)));
    Ok(())
}
